<template>
  <div><PageHeader eyebrow="REPORTING" title="Báo cáo" description="Read model báo cáo giúp xem nhanh class health mà không replay event history trong list/dashboard." /><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><div class="toolbar"><select v-model="selectedClassId" class="form-select" style="max-width:340px"><option value="">Chọn lớp học</option><option v-for="item in classes" :key="item.id" :value="item.id">{{ item.code }} · {{ item.name }}</option></select><span class="cell-subtle">Cập nhật {{ report?.updatedAt ? formatDateTime(report.updatedAt) : '—' }}</span></div><div v-if="loading" class="loading-state">Đang tải báo cáo…</div><template v-else-if="report"><div class="metrics-grid"><MetricCard icon="♙" label="Người học active" :value="report.activeEnrollmentCount" :hint="`${report.enrollmentCount} enrollment`" /><MetricCard icon="✓" label="Điểm đã publish" :value="report.publishedGradeCount" hint="Gradebook" /><MetricCard icon="◒" label="Điểm trung bình" :value="`${report.averageScorePercent}%`" hint="Theo class projection" /><MetricCard icon="◷" label="Điểm danh" :value="`${report.attendancePercentage}%`" hint="Attendance projection" /></div><div class="grid-two"><section class="panel"><div class="panel-heading"><h2>Assessment health</h2><span>{{ report.publishedActivityCount }}/{{ report.activityCount }} published</span></div><div class="progress-row"><div class="progress-row-head"><span>Submission</span><strong>{{ report.submissionCount }}</strong></div><div class="progress-track"><div class="progress-fill" :style="{ width: `${Math.min(100, report.submissionCount ? 100 : 0)}%` }"></div></div></div><div class="progress-row"><div class="progress-row-head"><span>Help requests</span><strong>{{ report.overviewHelpRequestedCount }}</strong></div></div><div class="progress-row"><div class="progress-row-head"><span>In progress</span><strong>{{ report.overviewInProgressCount }}</strong></div></div></section><section class="panel"><div class="panel-heading"><h2>Attendance</h2><span>{{ report.attendanceSessionCount }} sessions</span></div><div class="list-compact"><div class="list-compact-item"><div><strong>Có mặt</strong><span>{{ report.attendancePresentCount }}</span></div><StatusPill value="Present" /></div><div class="list-compact-item"><div><strong>Muộn</strong><span>{{ report.attendanceLateCount }}</span></div><StatusPill value="Late" /></div><div class="list-compact-item"><div><strong>Vắng</strong><span>{{ report.attendanceAbsentCount }}</span></div><StatusPill value="Absent" /></div></div></section></div></template><div v-else class="panel empty-state"><strong>Chọn lớp học</strong><span>Chọn lớp để xem báo cáo.</span></div></div>
</template>
<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'; import PageHeader from '../../../shared/ui/PageHeader.vue'; import MetricCard from '../../../shared/ui/MetricCard.vue'; import StatusPill from '../../../shared/ui/StatusPill.vue'; import { academicsApi, reportingApi } from '../../../shared/api/client'; import { formatDateTime, type ClassReport, type LearningClass } from '../../../shared/types'
const classes = ref<LearningClass[]>([]); const selectedClassId = ref(''); const report = ref<ClassReport | null>(null); const loading = ref(true); const error = ref(''); async function load() { if (!selectedClassId.value) { report.value = null; loading.value = false; return }; loading.value = true; try { report.value = await reportingApi.classSummary(selectedClassId.value) } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được báo cáo.') } finally { loading.value = false } }; async function boot() { try { classes.value = await academicsApi.classes(); if (classes.value[0]) selectedClassId.value = classes.value[0].id } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được lớp học.'); loading.value = false } }; watch(selectedClassId, load); onMounted(boot)
</script>
